sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', plan_id: '', plan_details: {} };
  try {
    var plugins = JSON.parse(inputs.plugins_to_upgrade);
    var planName = inputs.plan_name || 'Plugin Upgrade Plan';

    var startTime = new GlideDateTime();

    result.plan_details = {
      name: planName,
      start_time: startTime.getDisplayValue(),
      total_plugins: plugins.length,
      execution_order: [],
      status: 'initiated'
    };

    for (var i = 0; i < plugins.length; i++) {
      result.plan_details.execution_order.push({
        order: i + 1,
        plugin_name: plugins[i].name,
        sys_id: plugins[i].sys_id,
        target_version: plugins[i].available_version || plugins[i].target_version,
        status: 'pending'
      });
    }

    // Log plan to system log for audit
    var logGr = new GlideRecordSecure('syslog');
    logGr.initialize();
    logGr.setValue('message', 'Plugin Upgrade Plan initiated: ' + planName + ' with ' + plugins.length + ' plugins');
    logGr.setValue('source', 'x_snc_ai_upgrade_0');
    logGr.insert();

    result.plan_id = 'PLAN-' + startTime.getNumericValue();
    result.message = 'Upgrade plan created with ' + plugins.length + ' plugins in queue';
  } catch (e) {
    result.status = 'error';
    result.message = 'Failed to create upgrade plan: ' + e.message;
  }
  return result;
})(inputs);
